import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.find.js";
import "core-js/modules/es.iterator.for-each.js";
import "core-js/modules/es.iterator.map.js";
import "core-js/modules/es.iterator.some.js";
/*eslint-disable*/
import { get_vendor_workflows } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
import { get_all_org_users } from "@/mixins/GetUsersDropdown.js";
import OverlayComp from "@/components/OverlayComp.vue";
import VendorFormConf from "@/components/VendorManagement/VendorFormConf.vue";
import SnackBar from "@/components/SnackBar.vue";
export default {
  mixins: [get_all_org_users],
  components: {
    SnackBar,
    OverlayComp,
    VendorFormConf
  },
  data() {
    return {
      addData: false,
      stepsSelected: [],
      rolesRM: false,
      loading: false,
      initiaorRM: null,
      initiaorCheck: null,
      initiator: null,
      teamMember: null,
      teamMemberSelected: "",
      SnackBarComponent: {},
      overlay: false,
      selectedData: [],
      flowSteps: [{
        selected: false,
        text: "Initiator"
      }, {
        selected: false,
        text: "Initiator's Reporting Manager"
      }, {
        selected: false,
        text: "Roles"
      }],
      finalArray: [],
      vendorRecords: [],
      listSelected: [],
      roleSelected: "",
      itemSelIndex: 0,
      userList: [],
      workflowList: [],
      formObject: {},
      inputRecords: [],
      tableData: {},
      templete: [],
      search: "",
      vendorstep: 1,
      addedFlowSteps: [],
      queryCheck: false,
      templateSteps: {},
      radiobutton: null,
      expenseHead: null,
      startCheck: false
    };
  },
  async created() {
    this.$store.commit("Setnamesearch", "");
    this.overlay = true;
    await this.get_all_org_users();
    await this.fetch_users();
    await this.get_initiated_vendor();
  },
  watch: {
    addData: {
      async handler() {
        await this.get_all_org_users();
      }
    }
  },
  methods: {
    save_next_step() {
      this.addedFlowSteps = this.vendorRecords;
      // console.log(this.vendorRecords);
      localStorage.setItem("flowSteps1Info", JSON.stringify(this.vendorRecords));
      this.vendorstep = 2;
    },
    fetch_users() {
      this.userList = [];
      this.orgUsers.forEach(element => {
        if (element.user_status == "ACTIVE" && element.user_type != "CHATBOT") {
          this.userList.push({
            label: element.full_user_name,
            value: element.user_id
          });
        }
      });
      this.userList.sort((a, b) => a.label.localeCompare(b.label));
    },
    save_mutation(value) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: value,
        timeout: 5000,
        Top: true
      };
      this.vendorstep = 1;
      this.get_initiated_vendor();
      if (this.$refs.form) {
        this.$refs.form.reset();
      }
    },
    fetchclear() {
      this.expenseHead = null;
      this.initiator = null;
    },
    fetch_selected_data(value, type) {
      this.inputRecords = [];
      if (type == "teamMember") {
        this.inputRecords.push({
          step_no: this.vendorRecords.length + 1,
          name: this.teamMemberSelected.label,
          user_id: this.teamMemberSelected.value,
          user_type: "team_member",
          workflow_template: this.templete
        });
        this.expenseHead = null;
        this.initiator = null;
      } else if (type == "expense") {
        this.inputRecords.push({
          step_no: this.vendorRecords.length + 1,
          name: "Group Head",
          user_id: "N/A",
          user_type: "expense_group",
          workflow_template: this.templete
        });
        this.radiobutton = null;
        this.teamMemberSelected = "";
        this.initiator = null;
      } else if (type == "initator") {
        this.inputRecords.push({
          step_no: this.vendorRecords.length + 1,
          name: "Initiator",
          user_id: "N/A",
          user_type: "initiator",
          workflow_template: this.templete
        });
        this.radiobutton = null;
        this.teamMemberSelected = "";
        this.expenseHead = null;
      }
      // console.log(value);
    },
    error_msg(value) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: value,
        timeout: 5000,
        Top: true
      };
    },
    previous_step() {
      this.vendorstep = 1;
    },
    delete_record(val) {
      this.vendorRecords.splice(val, 1);
      let transformedArray = this.vendorRecords.map((item, index) => {
        return {
          ...item,
          step_no: index + 1
        };
      });
      this.vendorRecords = transformedArray;
      this.stepsSelected = [];
      this.radiobutton = null;
      this.expenseHead = null;
      this.teamMemberSelected = "";
    },
    close_dialog() {
      this.addData = false;
      this.initiaorRM = null;
      this.initiaorCheck = null;
      this.rolesRM = false;
      this.roleSelected = "";
      this.inputRecords = [];
      if (this.$refs.form) {
        this.$refs.form.reset();
        this.$refs.form.resetValidation();
      }
    },
    add_row(value) {
      this.inputRecords = [];
      this.teamMember = null;
      this.initiaorCheck = null;
      this.initiaorRM = null;
      this.itemSelIndex = value;
      this.addData = true;
    },
    add_vendordialog() {
      this.inputRecords = [];
      this.teamMember = null;
      this.initiaorCheck = null;
      this.initiaorRM = null;
      this.startCheck = true;
      this.addData = true;
    },
    async addvendor_items() {
      var newArray = this.vendorRecords;
      const {
        valid
      } = await this.$refs.form.validate();
      if (valid && (this.radiobutton != null || this.expenseHead != null || this.initiator != null) && !this.isNameAlreadyExists(this.inputRecords[0].name)) {
        if (this.startCheck == true) {
          this.vendorRecords.unshift(this.inputRecords[0]);
        } else {
          newArray.splice(this.itemSelIndex + 1, 0, this.inputRecords[0]);
          this.vendorRecords = newArray;
        }
        let transformedArray = this.vendorRecords.map((item, index) => {
          return {
            ...item,
            step_no: index + 1
          };
        });
        this.vendorRecords = transformedArray;
        this.addData = false;
        this.radiobutton = null;
        this.expenseHead = null;
        this.startCheck = false;
        this.initiator = null;
      } else {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: "Data Already Exists",
          timeout: 5000,
          Top: true
        };
      }
    },
    isNameAlreadyExists(exitsName) {
      return this.vendorRecords.some(obj => obj.name === exitsName);
    },
    get_input(index) {
      this.inputRecords = [];
      if (index == 2 && index != undefined) {
        this.inputRecords.push({
          step_no: this.vendorRecords.length + 1,
          name: this.teamMemberSelected.label,
          user_id: this.teamMemberSelected.value,
          user_type: "team_member",
          workflow_template: this.templete
        });
        this.teamMember = "member_team";
        this.initiaorCheck = null;
        this.initiaorRM = null;
        this.rolesRM = false;
      }
      this.finalArray = this.inputRecords;
    },
    async get_initiated_vendor() {
      try {
        let result = await API.graphql(graphqlOperation(get_vendor_workflows, {}));
        let response = JSON.parse(result.data.get_vendor_workflows);
        this.overlay = false;
        this.tableData = {};
        // console.log(response);
        if (response.Status == "SUCCESS") {
          let workfowData = response.data.find(obj => obj.form_unique_type === "VENDOR_REIMBURSEMENT");
          this.templete = workfowData.workflow_template;
          this.templateSteps = workfowData;
          this.tableData = workfowData;
          this.vendorRecords = this.tableData.workflow_approval_steps;
          this.queryCheck = true;
        } else {
          this.tableData = {};
          this.overlay = false;
        }
      } catch (error) {
        this.overlay = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    }
  }
};
